const game = new GF.Game({
  id: 'titan-core-salvage',
  title: 'TITAN CORE: SALVAGE',
  width: 960,
  height: 540,
  palette: ['#0d131a', '#00f0ff', '#ff4400', '#ffc800'],
  background: '#0d131a'
});

game.hitStop = function(dur = 0.06) {
  const sc = this.scenes[this.sceneName];
  if (sc) sc.freezeTimer = Math.max(sc.freezeTimer || 0, dur);
};

game.add('play', {
  init() {
    this.reset();
  },
  reset() {
    this.modal = null;
    this.modalTimer = 0;
    this.salvageItem = null;
    this.freezeTimer = 0;
    this.px = 220;
    this.py = 270;
    this.php = 100;
    this.pMaxHp = 100;
    this.dashTimer = 0;
    this.dashCd = 0;
    this.fireCd = 0;
    this.damageMult = 1;
    this.level = 1;
    this.bullets = [];
    this.telegraphs = [];
    this.embers = Array.from({ length: 30 }, () => ({
      x: GF.math.rand(960),
      y: GF.math.rand(540),
      vx: GF.math.rand(-25, 25),
      vy: GF.math.rand(-35, -10),
      sz: GF.math.rand(1, 3.5),
      alpha: GF.math.rand(0.3, 0.85)
    }));
    this.spawnTitan();
  },

  spawnTitan() {
    const hpM = 1 + (this.level - 1) * 0.45;
    this.titan = {
      x: 700,
      y: 270,
      attackCd: 1.0,
      subsystems: [
        { id: 'weapon', name: 'PLASMA CANNON', hp: 80 * hpM, maxHp: 80 * hpM, ox: -42, oy: -55, r: 24, destroyed: false, col: '#ff4400' },
        { id: 'shield', name: 'FORGE SHIELD', hp: 75 * hpM, maxHp: 75 * hpM, ox: -42, oy: 55, r: 22, destroyed: false, col: '#ffc800' },
        { id: 'core', name: 'TITAN REACTOR', hp: 200 * hpM, maxHp: 200 * hpM, ox: 0, oy: 0, r: 38, destroyed: false, col: '#00f0ff' }
      ]
    };
  },

  update(dt) {
    if (this.freezeTimer > 0) {
      this.freezeTimer -= dt;
      return;
    }

    for (const e of this.embers) {
      e.x += e.vx * dt;
      e.y += e.vy * dt;
      if (e.x < 0) e.x = 960;
      if (e.x > 960) e.x = 0;
      if (e.y < 0) e.y = 540;
    }

    if (this.modal) {
      this.updateModalInput(dt);
      return;
    }

    if (this.dashTimer > 0) this.dashTimer -= dt;
    if (this.dashCd > 0) this.dashCd -= dt;
    if (this.fireCd > 0) this.fireCd -= dt;

    let dx = 0, dy = 0;
    const keys = game.input.keys;
    if (keys['KeyA'] || keys['ArrowLeft']) dx -= 1;
    if (keys['KeyD'] || keys['ArrowRight']) dx += 1;
    if (keys['KeyW'] || keys['ArrowUp']) dy -= 1;
    if (keys['KeyS'] || keys['ArrowDown']) dy += 1;
    if (dx !== 0 && dy !== 0) { dx *= 0.7071; dy *= 0.7071; }

    if (game.input.pressed('Space') && this.dashCd <= 0) {
      this.dashTimer = 0.25;
      this.dashCd = 0.65;
      GF.Sfx.noise({ dur: 0.12, vol: 0.25, freq: 900 });
      game.burst(this.px, this.py, { count: 14, speed: 130, colors: ['#00f0ff', '#ffffff'], gravity: 0 });
    }

    const moveSpd = (this.dashTimer > 0 ? 540 : 230);
    this.px = GF.math.clamp(this.px + dx * moveSpd * dt, 40, 920);
    this.py = GF.math.clamp(this.py + dy * moveSpd * dt, 40, 500);

    const ptr = game.input.pointer;
    const isPrimaryFiring = ptr.down || ptr.clicked;
    const isMoving = dx !== 0 || dy !== 0;

    if ((isPrimaryFiring || isMoving) && this.fireCd <= 0) {
      this.fireCd = 0.13;
      let targetX = ptr.x;
      let targetY = ptr.y;
      if (!isPrimaryFiring) {
        let targetSub = this.titan.subsystems.find(s => !s.destroyed) || this.titan.subsystems[2];
        targetX = this.titan.x + targetSub.ox;
        targetY = this.titan.y + targetSub.oy;
      }
      const angle = Math.atan2(targetY - this.py, targetX - this.px);
      this.bullets.push({
        x: this.px,
        y: this.py,
        vx: Math.cos(angle) * 780,
        vy: Math.sin(angle) * 780,
        life: 1.2,
        damage: 15 * this.damageMult
      });
      GF.Sfx.beep({ freq: 540, to: 200, dur: 0.06, type: 'sawtooth', vol: 0.18 });
    }

    for (let i = this.bullets.length - 1; i >= 0; i--) {
      const b = this.bullets[i];
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      let hit = false;
      for (const sub of this.titan.subsystems) {
        if (sub.destroyed) continue;
        const sx = this.titan.x + sub.ox;
        const sy = this.titan.y + sub.oy;
        if (GF.math.dist(b.x, b.y, sx, sy) < sub.r + 8) {
          hit = true;
          sub.hp -= b.damage;
          game.addScore(10);
          game.burst(b.x, b.y, { count: 6, colors: ['#ffc800', '#ff4400'], speed: 110, gravity: 0 });
          GF.Sfx.beep({ freq: 170, dur: 0.04, vol: 0.12 });

          if (sub.hp <= 0) {
            sub.destroyed = true;
            game.addScore(250);
            game.hitStop(0.08);
            game.shake(8, 0.35);
            game.burst(sx, sy, { count: 32, colors: ['#ffc800', '#ff4400', '#00f0ff'], speed: 220, gravity: 40 });
            GF.Sfx.noise({ dur: 0.3, vol: 0.4, freq: 400 });
            this.modalTimer = 0;
            if (sub.id === 'core') {
              this.modal = 'extraction';
            } else {
              this.modal = 'salvage';
              this.salvageItem = sub;
            }
          }
          break;
        }
      }
      if (hit || b.life <= 0 || b.x < 0 || b.x > 960 || b.y < 0 || b.y > 540) {
        this.bullets.splice(i, 1);
      }
    }

    const wpnDestroyed = this.titan.subsystems[0].destroyed;
    const coreHpRatio = this.titan.subsystems[2].hp / this.titan.subsystems[2].maxHp;
    const enraged = coreHpRatio < 0.45 && !this.titan.subsystems[2].destroyed;

    this.titan.attackCd -= dt * (enraged ? 1.6 : 1.0) * (wpnDestroyed ? 0.65 : 1.0);
    if (this.titan.attackCd <= 0 && !this.titan.subsystems[2].destroyed) {
      this.titan.attackCd = GF.math.rand(1.7, 2.7);
      const atkType = GF.math.randInt(0, 2);
      if (atkType === 0) {
        const angle = Math.atan2(this.py - this.titan.y, this.px - this.titan.x);
        this.telegraphs.push({
          type: 'beam', x: this.titan.x, y: this.titan.y,
          angle: angle, len: 800, w: 34, timer: 0, maxTimer: enraged ? 0.65 : 0.95,
          dmg: 18
        });
      } else if (atkType === 1) {
        const angle = Math.atan2(this.py - this.titan.y, this.px - this.titan.x);
        this.telegraphs.push({
          type: 'cone', x: this.titan.x, y: this.titan.y,
          angle: angle, r: 440, spread: 0.85, timer: 0, maxTimer: enraged ? 0.75 : 1.1,
          dmg: 22
        });
      } else {
        this.telegraphs.push({
          type: 'ring', x: this.px + GF.math.rand(-35, 35), y: this.py + GF.math.rand(-35, 35),
          r: 58, timer: 0, maxTimer: enraged ? 0.65 : 1.0,
          dmg: 20
        });
      }
      GF.Sfx.beep({ freq: 220, to: 440, dur: 0.14, type: 'triangle', vol: 0.2 });
    }

    for (let i = this.telegraphs.length - 1; i >= 0; i--) {
      const t = this.telegraphs[i];
      t.timer += dt;
      if (t.timer >= t.maxTimer) {
        game.shake(6, 0.25);
        let hitPlayer = false;
        if (this.dashTimer <= 0) {
          if (t.type === 'ring') {
            if (GF.math.dist(this.px, this.py, t.x, t.y) < t.r) hitPlayer = true;
          } else if (t.type === 'beam') {
            const dx = Math.cos(t.angle), dy = Math.sin(t.angle);
            const px = this.px - t.x, py = this.py - t.y;
            const proj = px * dx + py * dy;
            if (proj >= 0 && proj <= t.len) {
              const perpDist = Math.abs(-px * dy + py * dx);
              if (perpDist < t.w / 2 + 12) hitPlayer = true;
            }
          } else if (t.type === 'cone') {
            const d = GF.math.dist(this.px, this.py, t.x, t.y);
            if (d < t.r) {
              let a = Math.atan2(this.py - t.y, this.px - t.x) - t.angle;
              while (a < -Math.PI) a += Math.PI * 2;
              while (a > Math.PI) a -= Math.PI * 2;
              if (Math.abs(a) < t.spread / 2) hitPlayer = true;
            }
          }
        }

        if (hitPlayer) {
          this.php -= t.dmg;
          game.flash('#ff4400', 0.45);
          game.shake(9, 0.3);
          GF.Sfx.noise({ dur: 0.2, vol: 0.4, freq: 250 });
          if (this.php <= 0) {
            this.php = 0;
            game.gameOver({ message: 'TITAN OVERWHELMED CORE' });
          }
        }
        game.burst(t.x, t.y, { count: 18, colors: ['#ff4400', '#ffc800'], speed: 180, gravity: 0 });
        GF.Sfx.noise({ dur: 0.15, vol: 0.3, freq: 500 });
        this.telegraphs.splice(i, 1);
      }
    }
  },

  updateModalInput(dt) {
    this.modalTimer += dt;
    const ptr = game.input.pointer;
    const keys = game.input.keys;

    if (this.modal === 'salvage') {
      let choice = -1;
      if (game.input.pressed('Digit1') || keys['KeyI'] || keys['KeyA']) choice = 0;
      else if (game.input.pressed('Digit2') || keys['KeyS'] || keys['KeyW']) choice = 1;
      else if (game.input.pressed('Digit3') || keys['KeyD'] || keys['Space']) choice = 2;
      else if (ptr.clicked) {
        if (ptr.y >= 310 && ptr.y <= 370) {
          if (ptr.x >= 220 && ptr.x <= 380) choice = 0;
          else if (ptr.x >= 400 && ptr.x <= 560) choice = 1;
          else if (ptr.x >= 580 && ptr.x <= 740) choice = 2;
        } else {
          choice = 1;
        }
      } else if (this.modalTimer > 1.8) {
        choice = 1;
      }

      if (choice === 0) {
        this.damageMult += 0.35;
        this.php = Math.min(this.pMaxHp, this.php + 20);
        game.flash('#00f0ff', 0.5);
        GF.Sfx.beep({ freq: 440, to: 880, dur: 0.2, type: 'triangle', vol: 0.4 });
        this.modal = null;
      } else if (choice === 1) {
        game.addScore(500);
        game.flash('#ffc800', 0.4);
        GF.Sfx.melody([[523, 0.08], [659, 0.1], [784, 0.12]]);
        this.modal = null;
      } else if (choice === 2) {
        this.php = Math.min(this.pMaxHp, this.php + 50);
        game.flash('#00f0ff', 0.3);
        GF.Sfx.beep({ freq: 300, to: 600, dur: 0.18, vol: 0.3 });
        this.modal = null;
      }
    } else if (this.modal === 'extraction') {
      let choice = -1;
      if (game.input.pressed('KeyE') || game.input.pressed('Digit1') || keys['KeyA']) choice = 0;
      else if (game.input.pressed('KeyV') || game.input.pressed('Digit2') || keys['KeyD']) choice = 1;
      else if (ptr.clicked) {
        if (ptr.y >= 310 && ptr.y <= 370) {
          if (ptr.x >= 280 && ptr.x <= 450) choice = 0;
          else if (ptr.x >= 510 && ptr.x <= 680) choice = 1;
        } else {
          choice = 0;
        }
      } else if (this.modalTimer > 2.0) {
        choice = 0;
      }

      if (choice === 0) {
        game.addScore(1000);
        game.win({ message: 'TITAN DISMANTLED & EXTRACTED!' });
      } else if (choice === 1) {
        this.level++;
        this.modal = null;
        this.spawnTitan();
        game.flash('#ff4400', 0.4);
        GF.Sfx.beep({ freq: 200, to: 600, dur: 0.25, type: 'sawtooth' });
      }
    }
  },

  draw(ctx) {
    const bgGrad = ctx.createLinearGradient(0, 0, 960, 540);
    bgGrad.addColorStop(0, '#0a1018');
    bgGrad.addColorStop(1, '#131e2b');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, 960, 540);

    ctx.strokeStyle = 'rgba(0, 240, 255, 0.08)';
    ctx.lineWidth = 1;
    for (let x = 0; x < 960; x += 40) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, 540); ctx.stroke();
    }
    for (let y = 0; y < 540; y += 40) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(960, y); ctx.stroke();
    }

    for (const e of this.embers) {
      ctx.fillStyle = `rgba(255, 200, 0, ${e.alpha})`;
      ctx.beginPath(); ctx.arc(e.x, e.y, e.sz, 0, Math.PI * 2); ctx.fill();
    }

    for (const t of this.telegraphs) {
      const progress = t.timer / t.maxTimer;
      ctx.save();
      if (t.type === 'ring') {
        ctx.fillStyle = 'rgba(255, 68, 0, 0.25)';
        ctx.strokeStyle = '#ff4400'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(t.x, t.y, t.r, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
        ctx.fillStyle = 'rgba(255, 200, 0, 0.45)';
        ctx.beginPath(); ctx.arc(t.x, t.y, t.r * progress, 0, Math.PI * 2); ctx.fill();
      } else if (t.type === 'beam') {
        ctx.translate(t.x, t.y); ctx.rotate(t.angle);
        ctx.fillStyle = 'rgba(255, 68, 0, 0.25)'; ctx.strokeStyle = '#ff4400'; ctx.lineWidth = 2;
        ctx.fillRect(0, -t.w / 2, t.len, t.w); ctx.strokeRect(0, -t.w / 2, t.len, t.w);
        ctx.fillStyle = 'rgba(255, 200, 0, 0.5)';
        ctx.fillRect(0, -t.w / 2 * progress, t.len, t.w * progress);
      } else if (t.type === 'cone') {
        ctx.translate(t.x, t.y);
        ctx.fillStyle = 'rgba(255, 68, 0, 0.25)'; ctx.strokeStyle = '#ff4400'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(0, 0);
        ctx.arc(0, 0, t.r, t.angle - t.spread / 2, t.angle + t.spread / 2);
        ctx.closePath(); ctx.fill(); ctx.stroke();
        ctx.fillStyle = 'rgba(255, 200, 0, 0.45)';
        ctx.beginPath(); ctx.moveTo(0, 0);
        ctx.arc(0, 0, t.r * progress, t.angle - t.spread / 2, t.angle + t.spread / 2);
        ctx.closePath(); ctx.fill();
      }
      ctx.restore();
    }

    if (this.titan) {
      ctx.fillStyle = '#162332'; ctx.strokeStyle = '#00f0ff'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(this.titan.x, this.titan.y, 60, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.strokeStyle = '#ff4400'; ctx.lineWidth = 4;
      for (const sub of this.titan.subsystems) {
        if (sub.destroyed) continue;
        ctx.beginPath(); ctx.moveTo(this.titan.x, this.titan.y);
        ctx.lineTo(this.titan.x + sub.ox, this.titan.y + sub.oy); ctx.stroke();
      }
      for (const sub of this.titan.subsystems) {
        const sx = this.titan.x + sub.ox;
        const sy = this.titan.y + sub.oy;
        if (sub.destroyed) {
          ctx.fillStyle = '#222d3a';
          ctx.beginPath(); ctx.arc(sx, sy, sub.r * 0.7, 0, Math.PI * 2); ctx.fill();
          continue;
        }
        ctx.fillStyle = '#0d1520'; ctx.strokeStyle = sub.col; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(sx, sy, sub.r, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
        ctx.fillStyle = sub.col;
        ctx.beginPath(); ctx.arc(sx, sy, sub.r * 0.5, 0, Math.PI * 2); ctx.fill();
        const hpPct = Math.max(0, sub.hp / sub.maxHp);
        ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(sx, sy, sub.r + 5, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * hpPct);
        ctx.stroke();
      }
    }

    for (const b of this.bullets) {
      ctx.fillStyle = '#00f0ff';
      ctx.beginPath(); ctx.arc(b.x, b.y, 5, 0, Math.PI * 2); ctx.fill();
    }

    ctx.save();
    ctx.translate(this.px, this.py);
    if (this.dashTimer > 0) {
      ctx.strokeStyle = '#00f0ff'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(0, 0, 26, 0, Math.PI * 2); ctx.stroke();
    }
    ctx.fillStyle = '#101e2c'; ctx.strokeStyle = '#00f0ff'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#00f0ff';
    ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI * 2); ctx.fill();
    const ptr = game.input.pointer;
    const pAngle = Math.atan2(ptr.y - this.py, ptr.x - this.px);
    ctx.rotate(pAngle);
    ctx.fillStyle = '#00f0ff';
    ctx.fillRect(10, -3, 14, 6);
    ctx.restore();

    ctx.strokeStyle = '#00f0ff'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(ptr.x, ptr.y, 10, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ptr.x - 14, ptr.y); ctx.lineTo(ptr.x + 14, ptr.y); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ptr.x, ptr.y - 14); ctx.lineTo(ptr.x, ptr.y + 14); ctx.stroke();

    GF.Draw.roundRect(ctx, 20, 20, 220, 20, 4, 'rgba(13, 19, 26, 0.85)');
    const pHealthPct = Math.max(0, this.php / this.pMaxHp);
    GF.Draw.roundRect(ctx, 22, 22, 216 * pHealthPct, 16, 3, '#00f0ff');
    GF.Draw.text(ctx, `CORE INTEGRITY ${Math.ceil(this.php)}%`, 25, 50, { size: 13, color: '#00f0ff', align: 'left' });
    GF.Draw.text(ctx, `SECTOR ${this.level} TITAN`, 940, 25, { size: 14, color: '#ffc800', align: 'right' });

    if (this.modal === 'salvage' && this.salvageItem) {
      ctx.fillStyle = 'rgba(13, 19, 26, 0.88)';
      ctx.fillRect(0, 0, 960, 540);
      GF.Draw.roundRect(ctx, 180, 120, 600, 300, 12, '#121d28');
      ctx.strokeStyle = '#00f0ff'; ctx.lineWidth = 3;
      ctx.strokeRect(180, 120, 600, 300);
      GF.Draw.text(ctx, 'COMPONENT SEVERED!', 480, 160, { size: 28, color: '#ffc800', weight: '900' });
      GF.Draw.text(ctx, `SALVAGED: ${this.salvageItem.name}`, 480, 200, { size: 20, color: '#00f0ff' });
      GF.Draw.text(ctx, 'SELECT SALVAGE DIRECTIVE:', 480, 250, { size: 16, color: '#ffffff' });

      GF.Draw.roundRect(ctx, 220, 310, 160, 60, 6, '#00f0ff');
      GF.Draw.text(ctx, '[1] INSTALL', 300, 332, { size: 16, color: '#0d131a', weight: '800' });
      GF.Draw.text(ctx, '+DMG & Hull', 300, 352, { size: 12, color: '#0d131a' });

      GF.Draw.roundRect(ctx, 400, 310, 160, 60, 6, '#ffc800');
      GF.Draw.text(ctx, '[2] SECURE', 480, 332, { size: 16, color: '#0d131a', weight: '800' });
      GF.Draw.text(ctx, '+500 Score', 480, 352, { size: 12, color: '#0d131a' });

      GF.Draw.roundRect(ctx, 580, 310, 160, 60, 6, '#ff4400');
      GF.Draw.text(ctx, '[3] DISMANTLE', 660, 332, { size: 16, color: '#ffffff', weight: '800' });
      GF.Draw.text(ctx, 'Repair +50 HP', 660, 352, { size: 12, color: '#ffffff' });
    } else if (this.modal === 'extraction') {
      ctx.fillStyle = 'rgba(13, 19, 26, 0.9)';
      ctx.fillRect(0, 0, 960, 540);
      GF.Draw.roundRect(ctx, 220, 120, 520, 300, 12, '#121d28');
      ctx.strokeStyle = '#ffc800'; ctx.lineWidth = 3;
      ctx.strokeRect(220, 120, 520, 300);
      GF.Draw.text(ctx, 'TITAN REACTOR DESTROYED!', 480, 165, { size: 26, color: '#7dffb2', weight: '900' });
      GF.Draw.text(ctx, 'Chamber Cleared - Proceed or Extract?', 480, 220, { size: 18, color: '#ffffff' });

      GF.Draw.roundRect(ctx, 280, 310, 170, 60, 6, '#7dffb2');
      GF.Draw.text(ctx, '[E] EXTRACT', 365, 332, { size: 16, color: '#0d131a', weight: '800' });
      GF.Draw.text(ctx, '+1000 Victory Bonus', 365, 352, { size: 11, color: '#0d131a' });

      GF.Draw.roundRect(ctx, 510, 310, 170, 60, 6, '#ff4400');
      GF.Draw.text(ctx, '[V] VENTURE DEEPER', 595, 332, { size: 14, color: '#ffffff', weight: '800' });
      GF.Draw.text(ctx, 'Next Chamber +50% HP', 595, 352, { size: 11, color: '#ffffff' });
    }
    GF.Draw.vignette(ctx, 960, 540, 0.35);
  }
});

game.titleScreen({
  subtitle: 'WASD / Move | Space / Dash | Mouse / Aim & Fire | 1, 2, 3 / Directives',
  onStart: () => game.go('play')
});
